using System.Text.Json;
using Yukkuri.Simulation;
int passes=0,failures=0;
void Require(bool ok,string text){if(!ok)throw new Exception(text);}
void Check(string name,Action action){try{action();passes++;Console.WriteLine("PASS "+name);}catch(Exception e){failures++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
void Tick(WorldSimulation sim,double seconds){double end=sim.State.WorldSeconds+seconds;while(sim.State.WorldSeconds<end-1e-8){sim.AdvanceInteractionPresentation(.025);sim.Advance(.025);}}
WorldSimulation Yard(int count=1){var sim=WorldSimulation.CreateCourtyardEconomy(20261103);sim.State.Creatures.RemoveRange(count,3-count);sim.State.Shelters.Clear();sim.State.RoomObjects.Clear();sim.State.SupplyStations.Clear();sim.State.AutonomousBreeding=false;sim.Config.WildGrassEnabled=false;
foreach(var c in sim.State.Creatures){GrowthRules.Initialize(c,false);c.X=c.TargetX=0;c.Z=c.TargetZ=3;c.Fullness=c.Energy=c.Interaction.Hydration=100;c.Fear=c.Pain=0;c.Interaction.Sleepiness=0;c.Interaction.NextAutonomyAt=1e9;c.Family.NextCareAt=c.Family.NextSocialAt=c.Family.NextBreedingDecisionAt=1e9;c.Family.CompanionTargetId=null;c.Family.CompanionUntil=0;c.Interaction.Emotion.Manmanlai=80;c.Interaction.Emotion.Alarm=0;c.Interaction.ToyInterest=0;c.DecisionIn=1e9;}
return sim;}
foreach(int speed in WorldSimulation.CourtyardSpeeds)foreach(double water in new[]{19.1,19.5,19.9})Check($"rest/drink priority water={water} speed={speed}",()=>{var sim=Yard();sim.SetCourtyardSpeed(speed);var c=sim.Selected!;c.Interaction.Sleepiness=95;c.Interaction.Hydration=water;sim.State.RoomObjects.Add(new(){Id="bed",Kind=RoomObjectKind.Cushion,RegionId=c.RegionId,X=0,Z=3});sim.State.RoomObjects.Add(new(){Id="water",Kind=RoomObjectKind.Water,RegionId=c.RegionId,X=1.8,Z=3,Portions=4});Tick(sim,15);Require(c.Interaction.Hydration>70,"stood at cushion instead of drinking: "+c.Activity);Require(c.Interaction.Sleepiness<95,"did not resume rest");});
Check("shared exit parking never owns an already cleared body",()=>{var sim=Yard(2);sim.State.ShelterStock=1;Require(sim.PlaceShelter(0,-5).Success,"place");var h=sim.State.Shelters.Single();var c=sim.State.Creatures[0];var blocker=sim.State.Creatures[1];c.X=1.5;c.Z=0;c.TargetX=1.5;c.TargetZ=0;blocker.X=0;blocker.Z=0;blocker.Interaction.Restraint=RestraintKind.Box;h.Residents.Add(new(){CreatureId=c.Id,Slot=4,Phase=ShelterVisitPhase.Exiting,ExitRequested=true});Tick(sim,5);Require(h.Residents.All(v=>v.CreatureId!=c.Id),"stale outdoor exit reservation");});
Check("occupied cushion falls back to real ground rest",()=>{var sim=Yard(3);sim.State.RoomObjects.Add(new(){Id="bed",Kind=RoomObjectKind.Cushion,RegionId="home",X=0,Z=3});for(int n=0;n<3;n++){var c=sim.State.Creatures[n];c.X=(n-1)*1.5;c.TargetX=c.X;c.Interaction.Sleepiness=95;}Tick(sim,25);Require(sim.State.Creatures.All(c=>c.Interaction.Sleepiness<95),"rest search never yields");});
Check("overlapping bodies can walk out without a landing event",()=>{var sim=Yard(3);for(int n=0;n<3;n++){var c=sim.State.Creatures[n];double a=n*Math.Tau/3;c.X=Math.Cos(a)*.15;c.Z=3+Math.Sin(a)*.15;c.TargetX=Math.Cos(a)*3;c.TargetZ=3+Math.Sin(a)*3;}Tick(sim,5);foreach(var c in sim.State.Creatures)foreach(var b in sim.State.Creatures.Where(b=>b!=c))Require(Math.Sqrt(Math.Pow(c.X-b.X,2)+Math.Pow(c.Z-b.Z,2))>=WorldSimulation.InteractionFootprint(c)+WorldSimulation.InteractionFootprint(b)-.0001,"interpenetration permanently blocks movement");});
Check("rest interruption seeks unavailable water instead of holding at bed",()=>{var sim=Yard();var c=sim.Selected!;c.Interaction.Hydration=19;c.Interaction.Sleepiness=95;sim.State.RoomObjects.Add(new(){Id="bed",Kind=RoomObjectKind.Cushion,RegionId="home",X=0,Z=3});Tick(sim,4);Require(!c.Interaction.Resting&&c.Interaction.LastWalkAt>0,"rest still owns autonomy without supplies");Require(sim.ExplainLifeActivity(c.Id).Action!="正在休息","false sleeping UI");});
Check("resource removed during approach releases target",()=>{var sim=Yard();var c=sim.Selected!;c.Fullness=40;var meal=new RoomObject{Id="meal",Kind=RoomObjectKind.Meal,RegionId="home",X=3,Z=3,Portions=4};sim.State.RoomObjects.Add(meal);Tick(sim,1);sim.State.RoomObjects.Remove(meal);Tick(sim,8);Require(c.Interaction.ResourceTargetId!=meal.Id&&c.Interaction.LastWalkAt>2,"stale target");});
Check("persistent follow yields to needed rest",()=>{var sim=Yard();var c=sim.Selected!;c.Interaction.FollowPlayer=true;c.Interaction.Sleepiness=95;Tick(sim,4);Require(!c.Interaction.FollowPlayer&&c.Interaction.Resting&&c.Interaction.Sleepiness<95,"follow/rest lock");});
Check("rest does not mask active eating",()=>{var sim=Yard();var c=sim.Selected!;c.Interaction.Sleepiness=95;c.Interaction.RestRemaining=40;c.Interaction.EatingRemaining=1;c.Interaction.EatingKind=IntakeKind.Water;Tick(sim,4);Require(c.Interaction.EatingRemaining==0&&c.Interaction.Resting,"accepted bite never completes");});
Check("overlap recovery leaves a restrained neighbour fixed",()=>{var sim=Yard(2);var c=sim.State.Creatures[0];var b=sim.State.Creatures[1];c.X=.1;c.TargetX=3;b.Interaction.Restraint=RestraintKind.Box;double bx=b.X,bz=b.Z;Tick(sim,5);Require(b.X==bx&&b.Z==bz,"moved restrained neighbour");Require(Math.Abs(c.X-b.X)>WorldSimulation.InteractionFootprint(c)+WorldSimulation.InteractionFootprint(b)-.01,"did not escape overlap");});
Check("paused and close-up time never starts autonomy recovery",()=>{foreach(bool close in new[]{false,true}){var sim=Yard(3);sim.State.Settings.Pause=!close;sim.State.Mode=close?PlayMode.CloseUp:PlayMode.Management;for(int n=0;n<100;n++){sim.AdvanceInteractionPresentation(.025);sim.Advance(.025);}Require(sim.State.WorldSeconds==0&&sim.State.Creatures.All(c=>c.X==0&&c.Z==3),"autonomy runs while frozen");}});
if(args.Length>0)Check("player save replay",()=>{var state=JsonSerializer.Deserialize<WorldState>(File.ReadAllText(args[0]),SaveStore.JsonOptions)!;var sim=new WorldSimulation(state);sim.State.Settings.Pause=false;sim.State.Mode=PlayMode.Management;sim.SetCourtyardSpeed(1);using var log=new StreamWriter(args.Length>1?args[1]:"replay.jsonl");for(int n=0;n<=12000;n++){if(n%400==0)foreach(var c in sim.State.Creatures)log.WriteLine(JsonSerializer.Serialize(new{t=sim.State.WorldSeconds,c.Name,c.X,c.Z,c.Activity,c.Energy,c.Fullness,c.Interaction.Hydration,c.Interaction.RestRemaining,c.Interaction.Resting,c.Interaction.Sleepiness,c.Interaction.LastWalkAt}));sim.AdvanceInteractionPresentation(.025);sim.Advance(.025);}SaveStore.Validate(sim.State);});
Console.WriteLine($"RESULT {passes} passed, {failures} failed");return failures==0?0:1;
